    await start();
    assert.equal(await (await fetch(base + projectPath)).text(), finalPage);
    assert.match(await (await fetch(base)).text(), /data-testid="project-summary">1\/2 completed/);
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
